21	/// Return `true` if the `Stmt` is a compound statement (as opposed to a simple statement).
22	pub const fn is_compound_statement(stmt: &Stmt) -> bool {
23	    matches!(
24	        stmt,
25	        Stmt::FunctionDef(_)
26	            | Stmt::ClassDef(_)
27	            | Stmt::While(_)
28	            | Stmt::For(_)
29	            | Stmt::Match(_)
30	            | Stmt::With(_)
31	            | Stmt::If(_)
32	            | Stmt::Try(_)
33	    )
34	}
