///
/// The variants are ordered by severity so that [`SideEffect::merge`] can rely
/// on the derived [`Ord`] implementation: `Absent < Possible < Present`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub enum SideEffect {
    /// The expression is definitely side-effect-free.
    Absent,
    /// The expression may have side effects (e.g., an f-string interpolation
    /// may invoke `__format__` or `__str__`).
    Possible,
    /// The expression is assumed to have side effects (e.g., a walrus operator
    /// or a function call).
    Present,
}

impl SideEffect {
    /// Returns `true` if the expression is assumed to have side effects.
    pub const fn is_present(self) -> bool {
        matches!(self, SideEffect::Present)
    }

    /// Returns `true` if the expression is definitely side-effect-free.
    pub const fn is_absent(self) -> bool {
        matches!(self, SideEffect::Absent)
    }

    /// Merge two [`SideEffect`] values, with [`SideEffect::Present`] taking
    /// precedence over [`SideEffect::Possible`], which takes precedence over
    /// [`SideEffect::Absent`].
    #[must_use]
    pub fn merge(self, other: Self) -> Self {
        self.max(other)
    }
}

/// Classify a single expression node (without recursing into its children).
fn single_expr_side_effect(expr: &Expr) -> SideEffect {
    match expr {
        // The walrus operator binds a name as a side effect.
        Expr::Named(_) => SideEffect::Present,
        // An f-string that interpolates a non-literal expression may invoke
        // `__format__` or `__str__`.
        Expr::FString(ast::ExprFString { value, .. }) => {
            if value.elements().any(|element| {
                element
                    .as_interpolation()
                    .is_some_and(|interpolation| !interpolation.expression.is_literal_expr())
            }) {
                SideEffect::Possible
            } else {
                SideEffect::Absent
            }
        }
        // Complex expressions that are assumed to have side effects.
        Expr::Await(_)
        | Expr::Call(_)
        | Expr::DictComp(_)
        | Expr::Generator(_)
        | Expr::ListComp(_)
        | Expr::SetComp(_)
        | Expr::Subscript(_)
        | Expr::Yield(_)
        | Expr::YieldFrom(_)
        | Expr::IpyEscapeCommand(_) => SideEffect::Present,
        _ => SideEffect::Absent,
    }
}

/// Traverse an expression and return the combined [`SideEffect`] of all of its
/// sub-expressions.
///
/// The traversal short-circuits and returns [`SideEffect::Present`] as soon as
/// a definitely side-effectful sub-expression is found.
///
/// Accepts a closure that determines whether a given name (e.g., `"list"`) is a Python builtin.
pub fn side_effect<F>(expr: &Expr, is_builtin: F) -> SideEffect
where
    F: Fn(&str) -> bool,
{
    let _ = is_builtin;
    let mut effect = SideEffect::Absent;
    any_over_expr(expr, |expr| {
        effect = effect.merge(single_expr_side_effect(expr));
        effect.is_present()
    });
    effect
}

